"""Synchronize package prose only after accepted data and page-by-page visual review."""
from pathlib import Path
import json,hashlib,zipfile
from docx import Document
R=Path(__file__).resolve().parents[1];P=R/'publication/array'
HIGHLIGHTS=['Matched feedback rules separate missing-evidence penalties from proof traffic.',
'Counterbalanced relay identities test three retained policies in 1,440 runs.',
'Recorded risk changes alter logits without changing archived relay choices.',
'Compiler optimization leaves 68 of 200 signed-receipt deadlines unmet.']
def main():
    if (P/'followup_edits.json').exists():raise ValueError('Follow-up manuscript requires scripts/finalize_followup_package.py; historical fixed counts must not overwrite the current package')
    review=json.loads((P/'remediation_visual_review.json').read_text());audit=json.loads((P/'remediation_manuscript_audit.json').read_text());a=json.loads((R/'outputs/remediation_v1/analysis.json').read_text())
    assert review['status']=='passed_page_by_page_review' and audit['status']=='passed' and a['runs']==1440
    current_docx=hashlib.sha256((P/'Array_Manuscript.docx').read_bytes()).hexdigest();current_pdf=hashlib.sha256((P/'Array_Manuscript.pdf').read_bytes()).hexdigest()
    if review['docx_sha256']!=current_docx or audit['final_docx_sha256']!=current_docx or review['pdf_sha256']!=current_pdf:raise ValueError('Stale manuscript audit or visual review; render and inspect the actual files')
    d=Document(P/'Array_Manuscript.docx');abstract=next(d.paragraphs[i+1].text for i,p in enumerate(d.paragraphs) if p.text=='Abstract');title=next(p.text for p in d.paragraphs if p.style.name=='Title')
    checks=dict(pages=review['pages'],rendered_pages=review['pages'],abstract_words=len(abstract.split()),figures=14,tables=12,references=25,native_equations=10,inline_exhibits={'figures_in_body':14,'tables_in_body':12,'algorithm_in_body':1},all_pages_visually_verified=True,visual_review='Every final page reviewed; unchanged pages rebound by pixel identity after pagination correction',python_regression_tests_passed=142,regression_source_commit='bc2f9a19bd26778f55aa4e2d209ccc5374b27e05',full_suite_rerun_this_revision=True,remediation_runs=1440,independent_geometry_blocks=12,policy_checkpoints=3,historical_evidence_families={'original_feedback_runs':750,'authenticated_transfer_runs':180,'ns3_factorial_runs':240,'original_cooja_runs':600},physical_validation=False,production_mcu_security_validated=False,original_signed_deadline_compliance=False,coauthor_approval_certified=False,authenticated_portal_checked=False,submission_certified=False,full_validation_complete=False,pdf_sha256=review['pdf_sha256'],docx_sha256=review['docx_sha256'])
    (P/'document_checks.json').write_text(json.dumps(checks,indent=2)+'\n');assert all(len(h)<=85 for h in HIGHLIGHTS);(P/'Highlights.txt').write_text('\n'.join(HIGHLIGHTS)+'\n')
    hd=Document();hd.add_heading('Highlights',0)
    for text in HIGHLIGHTS:hd.add_paragraph(text,style='List Bullet')
    hd.save(P/'Highlights.docx')
    (P/'Array_Manuscript.md').write_text('\n\n'.join(p.text for p in d.paragraphs)+'\n')
    with zipfile.ZipFile(P/'Array_Figures_PNG_PDF_SVG.zip','w',compression=zipfile.ZIP_DEFLATED) as z:
        for folder in ['figures','review_figures','postfreeze_figures','cooja_figures','remediation_figures']:
            for f in sorted((P/folder).glob('fig*')):
                if f.suffix in ['.png','.pdf','.svg']:z.write(f,str(f.relative_to(P)))
    summary=f"The paper contains {review['pages']} visually inspected pages, a {len(abstract.split())}-word abstract, fourteen figures, twelve tables, twenty-five references and ten preserved native equations. A new separately frozen 1,440-run matched Cooja study counterbalances relay identity and physical attacker position across twelve perturbed geometries and three retained checkpoints. Its factorial analysis is separate from the retained 750/180/240/600 families."
    (P/'README.md').write_text('# Array review package\n\n'+summary+'\n\nThe new matched arms share ACK gating, expiry, positive-credit and late-positive handling; only missing-evidence penalties and proof generation vary. The active reference retains separate semantics. Recorded logits change in 7,023 of 11,927 archived matched decisions without changing the selected relay; offline interventions establish sensitivity, not closed-loop performance.\n\nThe O3 emulator profile still misses 68/200 original signed deadlines. Physical RF/current, production MCU security, actual final author approvals and authenticated portal checks remain incomplete. This is an evidence-backed review package, not a submission certificate.\n\nSee [the concern matrix](../../docs/REMEDIATION_COMPLETION_REPORT.md), [reproduction commands](../../docs/REMEDIATION_REPRODUCTION.md), `remediation_manuscript_audit.json`, `remediation_visual_review.json` and `document_checks.json`. Durable raw archives and their hashes are identified in `outputs/remediation_v1/raw_archive.json`. Descriptive benign and factor-level summaries are in Remediation_Control_Supplement.md. Figures are data-derived PNG/PDF/SVG exports. Original tables, images and equations remain preserved; no generated hardware photography or synthetic results are included.\n')
    p=R/'README.md';s=p.read_text();end=s.index('> Historical transport stage:');p.write_text('## Current remediation and manuscript\n\n'+summary+' Full regression evidence and exact source revisions are retained under `outputs/remediation_regression`. The original signed deadline still has 68/200 misses after compiler-only O3 execution. Physical measurements, production security, actual author approvals and authenticated submission remain open.\n\nSee [the completion matrix](docs/REMEDIATION_COMPLETION_REPORT.md), [reproduction instructions](docs/REMEDIATION_REPRODUCTION.md) and [the paper package](publication/array/README.md). Historical stage descriptions below retain their original scope and are superseded by this current evidence summary.\n\n'+s[end:])
    for name in ['SUBMISSION_STATUS.md','ARRAY_TARGET_AND_VIRTUAL_STATUS.md','PENDING_VALIDATION_REGISTER.md']:
        (R/'docs'/name).write_text('# Current validation and submission status\n\n'+summary+'\n\nThe combined CC2538 emulator image executes routing, inference, hop authentication and signed receipts. Earlier host-only bridge descriptions refer to historical stages. O3 preserves 68/200 signed deadline misses; private-MAC receipts are a distinct endpoint. No physical RF/current, protected production key storage, authenticated physical provisioning, firmware authenticity or reset-safe MCU session validation has been acquired. Actual final coauthor consent and authenticated portal checks remain outstanding.\n\nThe canonical concern-by-concern record is [REMEDIATION_COMPLETION_REPORT.md](REMEDIATION_COMPLETION_REPORT.md). That file distinguishes resolved research work, unvalidated implementation, scientific limits and external/human blockers, with the exact next evidence needed. Historical stage reports and raw failures remain preserved. No message or submission was sent.\n')
    checklist=R/'docs/ARRAY_SUBMISSION_CHECKLIST.md';s=checklist.read_text().replace('eleven figures and twenty-four references','fourteen figures and twenty-five references').replace('The live extension adds Table 10.','The consolidated version contains twelve tables.').replace('The archive contains all eleven; older counts in historical commits are superseded.','Figure 12 is in cooja_figures; Figures 13–14 are in remediation_figures. The archive contains all fourteen; historical counts are superseded.');checklist.write_text(s)
    cover='DRAFT — not sent; final author approval and current portal requirements remain unconfirmed.\n\nDear Editors of Array,\n\nPlease consider “'+title+'”. The paper examines whether missing forwarding observations should be penalized or censored, while separating evidence semantics from proof traffic. It is a reproducible benchmark, not a new reinforcement-learning algorithm or a production-security validation.\n\nA separately frozen 1,440-run Cooja factorial study holds ACK gating, expiry, positive credit and late-positive handling constant across four arms. Twelve perturbed geometries include three retained checkpoints, node-ID permutations, both physical attacker positions and benign controls. Post-onset delivery uses geometry-block inference and a prespecified six-contrast Holm family. The active-proof implementation remains a separate reference, and the original 750/180/240/600 studies remain unpooled.\n\nExploratory reconstruction finds risk and logit changes without relay changes in the historical censored–frozen pairs; controlled offline interventions establish actor sensitivity without claiming radio improvement. A compiler-only O3 MCU pilot still misses 68/200 original signed deadlines. Physical RF/current, protected device keys and reset-safe production state remain unvalidated.\n\nCode, frozen protocols, captures, checkpoints, statistical scripts and negative results are available at https://github.com/DrShivamBhardwaj/JICCE_LA_CPPO_Reproducibility. The manuscript was substantially redesigned after rejection of JICCE-26-0057; it does not retain the earlier intrusion-classification framing.\n\nThe corresponding author supplied no-funding and no-competing-interest statements. Final author consent, contribution roles, exclusivity/overlap disclosures and authenticated submission declarations are not certified by this draft.\n\nSincerely,\nShivam Bhardwaj\nCorresponding author\n'
    (P/'Cover_letter_DRAFT.txt').write_text(cover)
if __name__=='__main__':main()
